CREATE TABLE "PlannedExpense" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "name" VARCHAR(100) NOT NULL, "amount" DECIMAL(19,4), "dueDate" DATE, "isActive" BOOLEAN NOT NULL DEFAULT true, "notes" VARCHAR(1000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PlannedExpense_pkey" PRIMARY KEY ("id"));
CREATE INDEX "PlannedExpense_userId_isActive_idx" ON "PlannedExpense"("userId", "isActive"); CREATE INDEX "PlannedExpense_userId_dueDate_idx" ON "PlannedExpense"("userId", "dueDate"); ALTER TABLE "PlannedExpense" ADD CONSTRAINT "PlannedExpense_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
